 public AudioBackend(Engine e,string driver,AsioOut pending,SourceChoice[] sources,OutputChoice target){engine=e;try{foreach(var s in sources){e.Inputs.Add(new Input(s));if(e.Partner!=null)e.Partner.Inputs.Add(new Input(s));}if(e.InputMonitor)e.SetInputMonitor(true);if(driver!=null){asio=pending??new AsioOut(driver);asio.ChannelOffset=target.Offset;asio.InputChannelOffset=0;asio.AudioAvailable+=OnAsio;asio.PlaybackStopped+=(s,a)=>{if(a.Exception!=null&&!disposed)e.Error="ASIO · "+a.Exception.Message;};asio.DriverResetRequest+=(s,a)=>{if(!disposed)e.Error="REOPEN_AUDIO";};asio.InitRecordAndPlayback(new LoopProvider(e),asio.DriverInputChannelCount,DSP.Rate);asio.Play();}else{using(var enumeration=new MMDeviceEnumerator()){var device=enumeration.GetDevice(target.Endpoint);endpoints.Add(device);output=new WasapiOut(device,AudioClientShareMode.Shared,true,40);output.PlaybackStopped+=(s,a)=>{if(a.Exception!=null&&!disposed)e.Error=a.Exception.Message;};output.Init(new LoopProvider(e));int index=0;foreach(var group in sources.GroupBy(x=>x.Endpoint)){var endpoint=enumeration.GetDevice(group.Key);endpoints.Add(endpoint);var capture=new CompatibleCapture(endpoint,CaptureFormat.Find(endpoint));captures.Add(capture);var decoder=new NativeCapture(capture.WaveFormat);int nativeChannels=capture.WaveFormat.Channels;if(group.Any(x=>x.Left>=nativeChannels||x.Right>=nativeChannels))throw new Exception("Input channel unavailable. Select channels 1/2.");var routes=new List<Input>();var partnerRoutes=new List<Input>();foreach(var choice in group){int routeIndex=Array.IndexOf(sources,choice);routes.Add(e.Inputs[routeIndex]);if(e.Partner!=null)partnerRoutes.Add(e.Partner.Inputs[routeIndex]);index++;}capture.DataAvailable+=(s,a)=>{if(disposed)return;try{e.PrepareRecordingSchedule();if(e.Partner!=null)e.Partner.PrepareRecordingSchedule();int count;var floats=decoder.Convert(a.Buffer,a.BytesRecorded,out count);float peak=0;lock(e.Gate){foreach(var route in routes)peak=Math.Max(peak,route.Feed(floats,count,nativeChannels,e.AudioFrame));}if(e.Partner!=null){lock(e.Partner.Gate)foreach(var route in partnerRoutes)peak=Math.Max(peak,route.Feed(floats,count,nativeChannels,e.Partner.AudioFrame));if(e.Partner.InputMode!=1)e.Partner.Peak=peak;}e.Peak=peak;}catch(Exception ex){e.Error=ex.Message;}};capture.RecordingStopped+=(s,a)=>{if(a.Exception!=null&&!disposed)e.Error=a.Exception.Message;};capture.StartRecording();}output.Play();}}}catch{Dispose();throw;}}
 void OnAsio(object sender,AsioAudioAvailableEventArgs a){if(disposed)return;try{engine.PrepareRecordingSchedule();if(engine.Partner!=null)engine.Partner.PrepareRecordingSchedule();int count=a.SamplesPerBuffer*a.InputBuffers.Length;if(asioSamples.Length<count)asioSamples=new float[count];a.GetAsInterleavedSamples(asioSamples);float peak=0;lock(engine.Gate){foreach(var input in engine.Inputs)peak=Math.Max(peak,input.Feed(asioSamples,count,a.InputBuffers.Length,engine.AudioFrame));}if(engine.Partner!=null){lock(engine.Partner.Gate)foreach(var input in engine.Partner.Inputs)peak=Math.Max(peak,input.Feed(asioSamples,count,a.InputBuffers.Length,engine.Partner.AudioFrame));if(engine.Partner.InputMode!=1)engine.Partner.Peak=peak;}engine.Peak=peak;}catch(Exception e){engine.Error=e.Message;}}
 public void Dispose(){if(disposed)return;disposed=true;if(asio!=null){asio.AudioAvailable-=OnAsio;asio.Dispose();asio=null;}foreach(var c in captures){c.StopRecording();c.Dispose();}captures.Clear();if(output!=null){output.Stop();output.Dispose();output=null;}foreach(var d in endpoints)d.Dispose();endpoints.Clear();}
}
}




























